using System;using System.IO;using System.Drawing;using System.Reflection;using System.Text;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Windows.Forms;using EanEtikety;
class Revision304Tests {
 static string dir;static int count;static BindingFlags flags=BindingFlags.NonPublic|BindingFlags.Instance;
 static T F<T>(object o,string n){return (T)o.GetType().GetField(n,flags).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,flags).Invoke(o,a);}static void Check(bool b,string n){count++;if(!b)throw new Exception(n);}
 [DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr h,int m,IntPtr w,IntPtr l);[DllImport("user32.dll")]static extern IntPtr GetDC(IntPtr h);[DllImport("user32.dll")]static extern int ReleaseDC(IntPtr h,IntPtr dc);[DllImport("gdi32.dll")]static extern IntPtr SelectObject(IntPtr dc,IntPtr h);[DllImport("gdi32.dll",CharSet=CharSet.Unicode)]static extern int GetTextFace(IntPtr dc,int n,StringBuilder text);
 static void Fonts(Control c){Check(c.Font.Name=="Source Sans 3","managed font "+c.GetType());if(c is TextBoxBase||c is ComboBox||c is Label||c is Button){var dc=GetDC(c.Handle);var hf=SendMessage(c.Handle,0x31,IntPtr.Zero,IntPtr.Zero);if(hf!=IntPtr.Zero){var old=SelectObject(dc,hf);var face=new StringBuilder(128);GetTextFace(dc,128,face);SelectObject(dc,old);File.AppendAllText(Path.Combine(dir,"font-audit.txt"),c.GetType().Name+": "+face+"\r\n");Check(face.ToString()=="Source Sans 3","native font "+c.GetType()+": "+face);}ReleaseDC(c.Handle,dc);}if(c is ComboBox||c is DataGridView)return;foreach(Control child in c.Controls)Fonts(child);}
 static void Snap(MainForm f,string n){Application.DoEvents();var p=F<PreviewPanel>(f,"preview");using(var b=new Bitmap(p.Width,p.Height))p.DrawToBitmap(b,p.ClientRectangle);using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(dir,n+".png"));}}
 [STAThread]static void Main(string[] a){dir=a[0];Directory.CreateDirectory(dir);try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var f=new MainForm(Path.Combine(dir,"prefs.xml"))){f.Icon=new Icon(Path.Combine(TestPaths.RepositoryRoot,"assets","app.ico"));f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();var studio=F<TableLayoutPanel>(f,"studio");var commands=F<FlowLayoutPanel>(f,"headerCommands");Check(object.ReferenceEquals(commands,F<FlowLayoutPanel>(f,"editorTools")),"one shared toolbar");Check(studio.RowStyles[1].Height==0,"empty row removed");Fonts(f);var tips=F<UiToolTip>(f,"headerTips");int icons=0;foreach(Control c in commands.Controls)if(c is HeaderActionButton){icons++;Check(!string.IsNullOrEmpty(c.AccessibleName),"accessible name");Check(!string.IsNullOrEmpty(tips.GetToolTip(c)),"localized tooltip");Check(!tips.GetToolTip(c).Contains("()"),"no invented shortcut");}Check(icons==2&&commands.Controls.Count==9,"two history icons and seven named commands share one toolbar");
 foreach(var width in new[]{1440,1024,1440,1100}){f.Size=new Size(width,850);Call(f,"UpdateToolbarLayout");Check(studio.RowStyles[0].Height<=90,"compact toolbar height");Check(studio.RowStyles[1].Height==0,"no blank second row");foreach(Control c in commands.Controls)if(c.Visible)Check(c.Right<=commands.ClientSize.Width+1&&c.Bottom<=commands.ClientSize.Height+1,"no clipped control: "+c.AccessibleName);}
 f.Size=new Size(1440,900);Snap(f,"dark");Call(f,"ToggleTheme");Snap(f,"light");Call(f,"ToggleTheme");f.Size=f.MinimumSize;Snap(f,"minimum");f.WindowState=FormWindowState.Minimized;Application.DoEvents();f.WindowState=FormWindowState.Normal;Application.DoEvents();Check(studio.RowStyles[0].Height<=90&&studio.RowStyles[1].Height==0,"restore compact row");foreach(string language in Loc.Codes){F<ComboBox>(f,"language").SelectedIndex=Array.IndexOf(Loc.Codes,language);foreach(Control c in commands.Controls)if(c is HeaderActionButton)Check(c.AccessibleName==Loc.T(c.AccessibleName),"localized action");}F<ComboBox>(f,"language").SelectedIndex=0;Call(f,"Apply",LabelSettings.Default());f.Close();}File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS "+count+" assertions: one toolbar, named commands and accessible history tooltips, no clipping at 1024/1100/1440, minimize/restore, both themes, four languages, Source Sans 3 managed and native GDI font audit. Real monitor DPI and Windows caption rendering remain manual checks.");}catch(Exception e){File.WriteAllText(Path.Combine(dir,"failed.txt"),e.ToString());Environment.ExitCode=1;}}
}
